-- ===== Part 2: row-level security =====
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['ai_settings', 'ai_conversations', 'ai_messages', 'ai_runs', 'ai_tool_executions']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I USING (organization_id = pcp_current_org()) WITH CHECK (organization_id = pcp_current_org())',
      t
    );
  END LOOP;
END
$$;

-- ===== Part 3: tenant resolution for conversation routes (TenantGuard) =====
CREATE FUNCTION pcp_resolve_ai_conversation(p_id uuid, p_user uuid)
  RETURNS TABLE (organization_id uuid, product_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = public, pg_temp
  AS $$
    SELECT c.organization_id, c.product_id FROM ai_conversations c
    JOIN organization_members m ON m.organization_id = c.organization_id AND m.user_id = p_user
    WHERE c.id = p_id
  $$;

ALTER FUNCTION pcp_resolve_ai_conversation(uuid, uuid) OWNER TO pcp_rls_definer;
REVOKE ALL ON FUNCTION pcp_resolve_ai_conversation(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pcp_resolve_ai_conversation(uuid, uuid) TO pcp_app;
